-- Face-only local bench test. No seed employees or demo passwords.
create extension if not exists pgcrypto with schema extensions;
create table public.gp_profiles(id uuid primary key references auth.users on delete cascade, role text not null check(role in ('Admin','HR')), active boolean not null default true);
create table public.gp_setup(id boolean primary key default true check(id), claimed boolean not null default false);
insert into public.gp_setup values(true,false);
create table public.gp_employees(id text primary key check(length(id) between 1 and 40), name text not null, email text not null default '', department text not null default '', active boolean not null default true, face_enabled boolean not null default true, created_at timestamptz not null default now());
create table public.gp_zones(id uuid primary key default gen_random_uuid(), name text unique not null);
create table public.gp_doors(id uuid primary key default gen_random_uuid(), name text not null, zone_id uuid not null references public.gp_zones, unique(zone_id,name));
create table public.gp_devices(id text primary key, name text not null, door_id uuid not null references public.gp_doors, revoked boolean not null default false, last_seen timestamptz, firmware text, rssi integer, created_at timestamptz not null default now());
create unique index one_active_device_per_door on public.gp_devices(door_id) where not revoked;
create table public.gp_device_secrets(device_id text primary key references public.gp_devices on delete cascade, enrollment_hash text, enrollment_expires timestamptz, token_hash text, enrolled_at timestamptz);
create table public.gp_permissions(employee_id text references public.gp_employees on delete cascade, door_id uuid references public.gp_doors on delete cascade, starts time not null, ends time not null, primary key(employee_id,door_id), check(starts<ends));
create table public.gp_face_templates(employee_id text primary key references public.gp_employees on delete cascade, embedding jsonb not null, model text not null, image_path text not null, created_at timestamptz not null default now());
create table public.gp_events(id uuid primary key default gen_random_uuid(), request_id uuid not null, device_id text not null references public.gp_devices, door_id uuid not null references public.gp_doors, employee_id text references public.gp_employees, method text not null check(method='face'), status text not null check(status in ('processing','allowed','denied','error')), reason text not null, similarity real, image_hash text not null, created_at timestamptz not null default now(), unique(device_id,request_id));
create table public.gp_audit(id bigint generated always as identity primary key, actor uuid references auth.users on delete set null, action text not null, details jsonb not null default '{}', created_at timestamptz not null default now());
create or replace function public.gp_is_manager() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.gp_profiles where id=(select auth.uid()) and active and role in ('Admin','HR'))$$;
revoke all on function public.gp_is_manager() from public; grant execute on function public.gp_is_manager() to authenticated;
alter table public.gp_profiles enable row level security;
create policy profile_read on public.gp_profiles for select to authenticated using(id=(select auth.uid()));
alter table public.gp_setup enable row level security;
alter table public.gp_employees enable row level security;
alter table public.gp_zones enable row level security;
alter table public.gp_doors enable row level security;
alter table public.gp_devices enable row level security;
alter table public.gp_device_secrets enable row level security;
alter table public.gp_permissions enable row level security;
alter table public.gp_face_templates enable row level security;
alter table public.gp_events enable row level security;
alter table public.gp_audit enable row level security;
create policy manager_read on public.gp_employees for select to authenticated using(public.gp_is_manager());
create policy manager_read on public.gp_zones for select to authenticated using(public.gp_is_manager());
create policy manager_read on public.gp_doors for select to authenticated using(public.gp_is_manager());
create policy manager_read on public.gp_devices for select to authenticated using(public.gp_is_manager());
create policy manager_read on public.gp_permissions for select to authenticated using(public.gp_is_manager());
create policy manager_read on public.gp_events for select to authenticated using(public.gp_is_manager());
create policy manager_read on public.gp_audit for select to authenticated using(public.gp_is_manager());
-- No client policies for device secrets, setup, biometric vectors or Storage objects.
revoke all on public.gp_device_secrets,public.gp_face_templates,public.gp_setup from anon,authenticated;
grant select on public.gp_profiles,public.gp_employees,public.gp_zones,public.gp_doors,public.gp_devices,public.gp_permissions,public.gp_events,public.gp_audit to authenticated;
grant all on all tables in schema public to service_role;
grant usage, select on all sequences in schema public to service_role;
create or replace function public.gp_claim_setup() returns boolean language plpgsql security definer set search_path='' as $$declare ok boolean; begin update public.gp_setup set claimed=true where id and not claimed returning true into ok; return coalesce(ok,false);end$$;
revoke all on function public.gp_claim_setup() from public,anon,authenticated; grant execute on function public.gp_claim_setup() to service_role;
create or replace function public.gp_enroll_device(p_device text,p_code_hash text,p_token_hash text) returns boolean language plpgsql security definer set search_path='' as $$declare ok boolean;begin update public.gp_device_secrets s set token_hash=p_token_hash,enrollment_hash=null,enrolled_at=now() where s.device_id=p_device and s.token_hash is null and s.enrollment_hash=p_code_hash and s.enrollment_expires>now() and exists(select 1 from public.gp_devices d where d.id=s.device_id and not d.revoked) returning true into ok;return coalesce(ok,false);end$$;
revoke all on function public.gp_enroll_device(text,text,text) from public,anon,authenticated; grant execute on function public.gp_enroll_device(text,text,text) to service_role;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('gatepass-faces','gatepass-faces',false,2097152,array['image/jpeg']) on conflict(id) do nothing;
